#!/usr/bin/env python3
"""
Compare Rust and Erlang VMSA page hex dumps byte-by-byte.
Paste the hex strings below and run the script.
"""

# Paste Rust's full VMSA page hex here (from [SNP_DEBUG] Rust VMSA page (BSP, full 4096 bytes))
RUST_VMSA_HEX = """

"""

# Paste Erlang's full VMSA page hex here (from full_vmsa_page_hex in create_vmsa_page_complete log)
ERLANG_VMSA_HEX = """

"""

def hex_to_bytes(hex_str):
    """Convert hex string to bytes, removing whitespace."""
    hex_str = hex_str.strip().replace('\n', '').replace(' ', '')
    return bytes.fromhex(hex_str)

def compare_vmsa_pages(rust_hex, erlang_hex):
    """Compare two VMSA pages byte-by-byte and report differences."""
    rust_bytes = hex_to_bytes(rust_hex)
    erlang_bytes = hex_to_bytes(erlang_hex)
    
    print(f"Rust VMSA size: {len(rust_bytes)} bytes")
    print(f"Erlang VMSA size: {len(erlang_bytes)} bytes")
    print()
    
    if len(rust_bytes) != len(erlang_bytes):
        print(f"ERROR: Size mismatch! Rust: {len(rust_bytes)}, Erlang: {len(erlang_bytes)}")
        return
    
    if len(rust_bytes) != 4096:
        print(f"WARNING: Expected 4096 bytes, got {len(rust_bytes)}")
    
    differences = []
    for i in range(len(rust_bytes)):
        if rust_bytes[i] != erlang_bytes[i]:
            differences.append((i, rust_bytes[i], erlang_bytes[i]))
    
    if not differences:
        print("✓ VMSA pages are IDENTICAL!")
        return
    
    print(f"Found {len(differences)} byte differences:")
    print()
    
    # Group differences by region for easier analysis
    regions = {
        "Segment Registers (0x0-0x9F)": (0, 0xA0),
        "Control Registers (0xD0-0x1CF)": (0xD0, 0x100),
        "General Registers (0x1F8-0x2F7)": (0x1F8, 0x100),
        "Other Registers (0x300-0x3FF)": (0x300, 0x100),
        "Floating Point (0x400-0x66F)": (0x400, 0x270),
    }
    
    for region_name, (start, size) in regions.items():
        region_diffs = [d for d in differences if start <= d[0] < start + size]
        if region_diffs:
            print(f"\n{region_name}:")
            for offset, rust_val, erlang_val in region_diffs[:20]:  # Show first 20
                print(f"  Offset 0x{offset:03X}: Rust=0x{rust_val:02X}, Erlang=0x{erlang_val:02X}")
            if len(region_diffs) > 20:
                print(f"  ... and {len(region_diffs) - 20} more differences in this region")
    
    # Show all differences in detail (first 100)
    print(f"\n\nAll differences (showing first 100):")
    for offset, rust_val, erlang_val in differences[:100]:
        # Show context (8 bytes before and after)
        context_start = max(0, offset - 8)
        context_end = min(len(rust_bytes), offset + 9)
        rust_context = rust_bytes[context_start:context_end]
        erlang_context = erlang_bytes[context_start:context_end]
        rust_hex = ' '.join(f'{b:02x}' for b in rust_context)
        erlang_hex = ' '.join(f'{b:02x}' for b in erlang_context)
        marker_pos = (offset - context_start) * 3
        marker = ' ' * marker_pos + '^^'
        print(f"Offset 0x{offset:03X}:")
        print(f"  Rust:   {rust_hex}")
        print(f"  Erlang: {erlang_hex}")
        print(f"          {marker}")
        print()
    
    if len(differences) > 100:
        print(f"... and {len(differences) - 100} more differences")

def check_key_fields(rust_hex, erlang_hex):
    """Check specific key fields that we know about."""
    rust_bytes = hex_to_bytes(rust_hex)
    erlang_bytes = hex_to_bytes(erlang_hex)
    
    key_fields = {
        "CS Base (0x18-0x1F)": (0x18, 8),
        "EFER (0xD0-0xD7)": (0xD0, 8),
        "CR4 (0x148-0x14F)": (0x148, 8),
        "RIP (0x178-0x17F)": (0x178, 8),
        "RDX (0x318-0x31F)": (0x318, 8),
        "SEV Features (0x3E8-0x3EF)": (0x3E8, 8),
        "MXCSR (0x3FC-0x3FF)": (0x3FC, 4),
        "X87 FCW (0x402-0x403)": (0x402, 2),
    }
    
    print("\nKey Field Comparison:")
    print("=" * 80)
    for field_name, (offset, size) in key_fields.items():
        rust_val = rust_bytes[offset:offset+size]
        erlang_val = erlang_bytes[offset:offset+size]
        rust_hex = ''.join(f'{b:02x}' for b in rust_val)
        erlang_hex = ''.join(f'{b:02x}' for b in erlang_val)
        match = "✓" if rust_val == erlang_val else "✗"
        print(f"{match} {field_name}:")
        print(f"   Rust:   {rust_hex}")
        print(f"   Erlang: {erlang_hex}")
        if rust_val != erlang_val:
            print(f"   MISMATCH!")
        print()

if __name__ == "__main__":
    # Remove placeholder text
    rust_hex = RUST_VMSA_HEX.replace("PASTE_RUST_VMSA_HEX_HERE", "").strip()
    erlang_hex = ERLANG_VMSA_HEX.replace("PASTE_ERLANG_VMSA_HEX_HERE", "").strip()
    
    if "PASTE" in rust_hex or "PASTE" in erlang_hex:
        print("ERROR: Please paste the hex values into the script first!")
        print("Replace PASTE_RUST_VMSA_HEX_HERE and PASTE_ERLANG_VMSA_HEX_HERE with the actual hex strings.")
        exit(1)
    
    if not rust_hex or not erlang_hex:
        print("ERROR: Hex strings are empty!")
        exit(1)
    
    print("Comparing Rust and Erlang VMSA pages...")
    print("=" * 80)
    print()
    
    check_key_fields(rust_hex, erlang_hex)
    compare_vmsa_pages(rust_hex, erlang_hex)

